'use strict';
// Farm data lives alongside the existing village save. Old inventories are preserved.
const GROW_MS=20000;
let farmView=true;
function ensureFarm(){if(!state.farm||!Array.isArray(state.farm.plots)){state.farm={plots:Array.from({length:6},()=>({seeded:false,wateredAt:0})),picked:0,sold:0};save()}return state.farm}
function plotStage(p,now=Date.now()){if(!p.seeded)return 0;if(!p.wateredAt)return 1;const t=Math.max(0,now-p.wateredAt);return t<GROW_MS*.4?2:t<GROW_MS?3:4}
function farmBlocked(){return weather().name.includes('폭우')&&!state.repaired}
const farmOriginalRender=render,farmOriginalPanel=renderPanel;
const scene=document.createElement('section');scene.id='farmScene';scene.className='farm-scene';scene.setAttribute('aria-label','직접 가꾸는 상추밭');
scene.innerHTML='<div class="farm-top"><h2>나의 작은 상추밭</h2><span id="farmWeather"></span></div><p class="farm-guide">빈 밭을 눌러 심고, 한 번 더 눌러 물을 주세요.</p><div id="farmAlert"></div><div class="plots" id="plots"></div><div class="farm-bottom"><span><span class="farm-basket">🧺</span>보관 중 <b id="farmStored">0</b>개</span><span class="farm-count" id="farmSize"></span><button id="expandFarm">밭 넓히기</button></div>';
$('#map').before(scene);
const switcher=document.createElement('div');switcher.className='view-switch';switcher.setAttribute('aria-label','지도 보기');switcher.innerHTML='<button id="farmView" class="active" aria-pressed="true">🌱 내 상추밭</button><button id="villageView" aria-pressed="false">🗺️ 전체 마을</button>';scene.before(switcher);
function setFarmView(value){if(window.villageNavigate){window.villageNavigate(value?'farm':'village');return}farmView=value;if(value){tab='work';state.place='work'}render()}
$('#farmView').onclick=()=>setFarmView(true);$('#villageView').onclick=()=>setFarmView(false);
function updatePlots(){const f=ensureFarm();if($('#plots').children.length!==f.plots.length){$('#plots').innerHTML=f.plots.map((_,i)=>`<button class="plot" data-plot="${i}" data-stage="0"><span class="plot-number">${i+1}번 밭</span><span class="sprite" aria-hidden="true"></span><span class="plot-label"></span><span class="plot-meter"><i></i></span></button>`).join('')}
const blocked=farmBlocked();f.plots.forEach((p,i)=>{const b=$(`[data-plot="${i}"]`),stage=plotStage(p),seconds=Math.max(0,Math.ceil((GROW_MS-(Date.now()-p.wateredAt))/1000));const label=['씨앗 심기','💧 물 주세요',`🌱 새싹 · ${seconds}초`,`자라는 중 · ${seconds}초`,'🥬 수확하기'][stage];b.dataset.stage=stage;b.disabled=blocked;b.querySelector('.plot-label').textContent=label;b.setAttribute('aria-label',`${i+1}번 밭 · ${label}`);const meter=b.querySelector('.plot-meter');meter.style.visibility=stage===2||stage===3?'visible':'hidden';meter.firstElementChild.style.width=Math.min(100,Math.max(0,(Date.now()-p.wateredAt)/GROW_MS*100))+'%'});$('#farmStored').textContent=state.stock[0];$('#farmSize').textContent=`${f.plots.length}칸의 텃밭`;const cost=f.plots.length===6?40:f.plots.length===8?60:80;$('#expandFarm').textContent=f.plots.length>=12?'최대 12칸 완성':`밭 +2칸 · ${cost}코인`;$('#expandFarm').disabled=f.plots.length>=12;$('#farmWeather').textContent=weather().icon+' '+weather().name;$('#farmAlert').innerHTML=blocked?'<div class="weather-note storm-repair-guide" role="status"><strong>🌧️ 오늘의 농장 미션 · 안전 복구</strong><span>폭우가 이어지는 동안은 씨앗을 심거나 물을 주고 수확할 수 없어요. 안전 복구 미션을 마치면 다시 농사할 수 있어요. 심어 둔 작물은 그대로 남아요.</span><button class="quiet" id="farmRepair">안전 복구 미션 시작</button></div>':'';if($('#farmRepair'))$('#farmRepair').onclick=()=>quiz('repair');if($('#farmPicked'))$('#farmPicked').textContent=f.picked;if($('#farmMoney'))$('#farmMoney').textContent=f.sold;if($('#farmSell'))$('#farmSell').disabled=state.stock[0]<1;}
renderPanel=function(){if(!farmView||tab!=='work'){farmOriginalPanel();return}const f=ensureFarm();$('#panel').innerHTML=`<span class="eyetag">PLANT · WATER · GROW</span><h2>손으로 가꾸는 첫 수확</h2><p>밭 한 칸을 눌러 보세요.<br>씨앗은 무료이고, 물을 주면 20초 동안 자라요. 실제 재배 시간과는 다른 체험 속도예요.</p><div class="farm-stage-strip"><span><b>🫘</b>씨앗</span><span><b>💧</b>물 주기</span><span><b>🌱</b>새싹</span><span><b>🥬</b>수확</span></div><div class="farm-task"><b>첫 목표 · 상추를 팔아 밭 넓히기</b><p>상추 1개는 마을 매입소에서 ${farmSalePrice()}코인에 팔 수 있어요. 40코인을 모으면 밭이 2칸 늘어나요.</p><small>장날에는 장터 시세로 판매하거나 친구와 교환해요.</small></div><div class="farm-mini-stats"><div><b id="farmPicked">${f.picked}</b><span>직접 수확한 상추</span></div><div><b id="farmMoney">${f.sold}</b><span>매입소 판매 수익</span></div></div><button class="primary wide" id="farmSell" ${state.stock[0]<1?'disabled':''}>🧺 상추 판매하기</button><button class="wide secondary" data-action="quiz" ${state.quizDay===state.day?'disabled':''}>${state.quizDay===state.day?'✓ 오늘의 직업 탐험 완료':'💡 오늘의 직업 퀴즈'}</button><p class="farm-saved">다른 직업을 골랐어도 상추밭을 체험할 수 있어요. 기존 물건과 코인은 그대로 유지됩니다.</p>`;$('#farmSell').onclick=showFarmSale;};
render=function(){ensureFarm();farmOriginalRender();scene.hidden=!farmView;$('#map').hidden=farmView;$('#farmView').classList.toggle('active',farmView);$('#villageView').classList.toggle('active',!farmView);$('#farmView').setAttribute('aria-pressed',String(farmView));$('#villageView').setAttribute('aria-pressed',String(!farmView));if(farmView){$('.world-heading h1').textContent='씨앗 하나부터, 나의 마을.';$('.eyebrow').textContent='CHAPTER 01 · 나의 첫 상추밭';if(!marketOpen())$('#phaseDesc').textContent='상추는 실제 20초 동안 자라요 · 다음 날 버튼은 장날과 날씨를 바꿔요.'}else{$('.world-heading h1').textContent='작은 일이 모여, 마을이 돼요.';$('.eyebrow').textContent='SEASON 01 · 함께 차리는 식탁'}updatePlots();save()};
function puff(b,text){const el=document.createElement('span');el.className='farm-floating';el.textContent=text;b.append(el);setTimeout(()=>el.remove(),1050);b.classList.remove('farm-action');void b.offsetWidth;b.classList.add('farm-action')}
$('#plots').addEventListener('click',e=>{const b=e.target.closest('[data-plot]');if(!b||farmBlocked())return;if(state.job===null){showJobs();return}const f=ensureFarm(),i=Number(b.dataset.plot),p=f.plots[i],stage=plotStage(p);if(stage===0){p.seeded=true;p.wateredAt=0;puff(b,'🫘');toast('씨앗을 심었어요! 이 밭을 한 번 더 눌러 물을 주세요.')}else if(stage===1){p.wateredAt=Date.now();puff(b,'💧');toast('물을 줬어요! 새싹이 올라오고 20초 뒤 수확할 수 있어요.')}else if(stage===4){const amount=state.level+1;state.stock[0]+=amount;f.picked+=amount;f.plots[i]={seeded:false,wateredAt:0};log(`${state.name}이(가) ${i+1}번 밭에서 직접 키운 상추 ${amount}개를 수확했어요.`);puff(b,`🥬 +${amount}`);toast(`상추 ${amount}개를 수확했어요! 보관함에서 확인하세요.`);render()}else{toast('잘 자라고 있어요. 다른 밭을 가꾸며 조금만 기다려 주세요.')}save();updatePlots()});
function farmSalePrice(){return marketOpen()?price(0):Math.max(1,Math.floor(price(0)*.8))}
function showFarmSale(){if(state.stock[0]<1)return;const unit=farmSalePrice();modal(`<span class="eyebrow">마을 매입소 · 가상 거래</span><h2>직접 키운 상추를 팔아요</h2><p>${marketOpen()?'장날이라 장터 시세를 그대로 적용해요.':'매입소는 매일 열려요. 오늘 장터 시세의 80%를 적용하며 소수점은 버려요.'}</p><div class="farm-receipt">보관 중인 상추 <b>${state.stock[0]}개</b><br>한 개에 <b>${unit}코인</b></div><label for="sellCount">판매할 수량</label><input type="number" id="sellCount" min="1" max="${state.stock[0]}" step="1" value="${state.stock[0]}"><div class="dialog-actions"><button data-close>취소</button><button class="primary" id="confirmFarmSell">판매 확정</button></div><p id="saleError" role="status"></p>`);$('#confirmFarmSell').onclick=()=>{const n=Number($('#sellCount').value);if(!Number.isInteger(n)||n<1||n>state.stock[0]){$('#saleError').textContent='보관 중인 수량 안에서 1개 이상 입력해 주세요.';return}state.stock[0]-=n;state.coins+=n*unit;ensureFarm().sold+=n*unit;log(`마을 매입소에 상추 ${n}개를 팔아 ${n*unit}코인을 모았어요.`);close();render();toast(`🪙 ${n*unit}코인을 받았어요. 밭을 넓혀 보세요!`)}}
$('#expandFarm').onclick=()=>{const f=ensureFarm(),cost=f.plots.length===6?40:f.plots.length===8?60:80;if(f.plots.length>=12)return;if(state.coins<cost){toast(`${cost}코인이 필요해요. 수확한 상추를 매입소에 팔아 보세요.`);return}modal(`<h2>우리 밭을 넓힐까요?</h2><p>${cost}코인으로 빈 밭 2칸을 더해요.<br>${f.plots.length}칸 → ${f.plots.length+2}칸</p><div class="dialog-actions"><button data-close>취소</button><button class="primary" id="confirmExpand">밭 넓히기</button></div>`);$('#confirmExpand').onclick=()=>{if(state.coins<cost||f.plots.length>=12)return;state.coins-=cost;f.plots.push({seeded:false,wateredAt:0},{seeded:false,wateredAt:0});log(`밭을 2칸 넓혔어요. 이제 ${f.plots.length}칸을 가꿀 수 있어요.`);close();render();toast('새 밭이 생겼어요! 씨앗을 심어 보세요.')}};
// Keep the existing village, exchange and cooperation routes reachable.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab==='work'){farmView=true;render()}if(b.dataset.visit==='0'){setFarmView(true);close()}},false);
$('#help').onclick=()=>modal('<h2>내 손으로 키우는 상추</h2><p>① 빈 밭을 눌러 씨앗을 심어요.<br>② 같은 밭을 다시 누르면 물을 줘요.<br>③ 새싹과 어린 상추가 보이고, 20초 뒤 수확할 수 있어요.<br>④ 다 자란 상추를 누르면 보관함에 들어가요.<br>⑤ 매입소에 팔아 밭을 늘리거나, 장날 친구와 교환해요.</p><div class="notice">다음 날 버튼 없이도 작물이 자라요. 실제 재배와는 다른 체험용 시간입니다. 폭우 때는 안전 복구 후 다시 밭에 들어갈 수 있어요.</div><button class="primary wide" data-close>밭 가꾸러 가기</button>');
ensureFarm();render();setInterval(()=>{if(farmView&&!document.hidden)updatePlots()},300);
